css:
.flex {
  display: flex;
}
.h-\[60px\] {
  height: 60px;
}
.w-\[60px\] {
  width: 60px;
}
.w-full {
  width: 100%;
}
.items-center {
  align-items: center;
}
.justify-center {
  justify-content: center;
}
.overflow-hidden {
  overflow: hidden;
}
.rounded-full {
  border-radius: 9999px;
}
.bg-\[\#4070f4\] {
  --tw-bg-opacity: 1;
  background-color: rgb(64 112 244 / var(--tw-bg-opacity));
}
.bg-transparent {
  background-color: transparent;
}
.fill-white {
  fill: #fff;
}
.p-5 {
  padding: 1.25rem;
}
.px-4 {
  padding-left: 1rem;
  padding-right: 1rem;
}
.text-\[20px\] {
  font-size: 20px;
}
.font-normal {
  font-weight: 400;
}
.text-white {
  --tw-text-opacity: 1;
  color: rgb(255 255 255 / var(--tw-text-opacity));
}
.shadow-\[2px_2px_20px_rgba\(0\2c 0\2c 0\2c 0\.08\)\] {
  --tw-shadow: 2px 2px 20px rgba(0, 0, 0, 0.08);
  --tw-shadow-colored: 2px 2px 20px var(--tw-shadow-color);
  box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000),
    var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow);
}
.outline-none {
  outline: 2px solid transparent;
  outline-offset: 2px;
}
.duration-300 {
  transition-duration: 300ms;
}
.hover\:w-\[270px\]:hover {
  width: 270px;
}
.hover\:duration-300:hover {
  transition-duration: 300ms;
}
